diff --git a/internal/hosted/agent/guard.go b/internal/hosted/agent/guard.go
new file mode 100644
index 0000000..5c62bbb
--- /dev/null
+++ b/internal/hosted/agent/guard.go
@@ -0,0 +1,112 @@
+package agent
+
+import (
+	"context"
+	"errors"
+	"path"
+)
+
+// Guarded wraps a GitRepo with the privacy rules of a run. A model can ask to
+// read any file at the commit, not only those in the diff, so excluding a path
+// from the diff is not enough: the same policy has to hold for every tool.
+//
+//   - Allow decides whether a path may be shown to the model at all.
+//   - Redact rewrites text before it is returned, for secret-like values that
+//     appear in files that are otherwise allowed.
+//
+// Redaction is a safety net, not access control: it recognizes known secret
+// shapes and nothing else.
+type Guarded struct {
+	Repo   GitRepo
+	Allow  func(path string) (allowed bool, reason string)
+	Redact func(text string) string
+}
+
+var errExcluded = errors.New("path is excluded from model input")
+
+func (g Guarded) check(p string) error {
+	clean, err := repositoryPath(p)
+	if err != nil {
+		return err
+	}
+	if g.Allow != nil {
+		if allowed, _ := g.Allow(clean); !allowed {
+			return errExcluded
+		}
+	}
+	return nil
+}
+
+func (g Guarded) redact(text string) string {
+	if g.Redact == nil {
+		return text
+	}
+	return g.Redact(text)
+}
+
+func (g Guarded) ReadLines(ctx context.Context, scope Scope, p string, start, end int) (string, error) {
+	if err := g.check(p); err != nil {
+		return "", err
+	}
+	text, err := g.Repo.ReadLines(ctx, scope, p, start, end)
+	return g.redact(text), err
+}
+
+// Search over-fetches because excluded paths are filtered after the search,
+// and returns at most limit allowed hits.
+func (g Guarded) Search(ctx context.Context, scope Scope, query string, limit int) ([]SearchHit, error) {
+	hits, err := g.Repo.Search(ctx, scope, query, min(limit*4, 4*MaxSearchResults))
+	if err != nil {
+		return nil, err
+	}
+	allowed := make([]SearchHit, 0, len(hits))
+	for _, hit := range hits {
+		if g.check(hit.Path) != nil {
+			continue
+		}
+		hit.Snippet = g.redact(hit.Snippet)
+		if allowed = append(allowed, hit); len(allowed) >= limit {
+			break
+		}
+	}
+	return allowed, nil
+}
+
+func (g Guarded) Blame(ctx context.Context, scope Scope, p string, start, end int) ([]BlameLine, error) {
+	if err := g.check(p); err != nil {
+		return nil, err
+	}
+	lines, err := g.Repo.Blame(ctx, scope, p, start, end)
+	for i := range lines {
+		lines[i].Summary = g.redact(lines[i].Summary)
+	}
+	return lines, err
+}
+
+func (g Guarded) Log(ctx context.Context, scope Scope, p string, limit int) ([]Commit, error) {
+	if err := g.check(p); err != nil {
+		return nil, err
+	}
+	commits, err := g.Repo.Log(ctx, scope, p, limit)
+	for i := range commits {
+		commits[i].Summary = g.redact(commits[i].Summary)
+	}
+	return commits, err
+}
+
+// ListFiles hides excluded files, so a model is not even told they exist.
+// Directories are always listed; their contents are filtered when listed.
+func (g Guarded) ListFiles(ctx context.Context, scope Scope, directory string) ([]string, error) {
+	entries, err := g.Repo.ListFiles(ctx, scope, directory)
+	if err != nil {
+		return nil, err
+	}
+	visible := make([]string, 0, len(entries))
+	for _, entry := range entries {
+		if len(entry) > 0 && entry[len(entry)-1] != '/' && entry[0] != '[' && g.check(path.Join(directory, entry)) != nil {
+			continue
+		}
+		visible = append(visible, entry)
+	}
+	return visible, nil
+}

diff --git a/internal/hosted/agent/guard_test.go b/internal/hosted/agent/guard_test.go
new file mode 100644
index 0000000..652e2e1
--- /dev/null
+++ b/internal/hosted/agent/guard_test.go
@@ -0,0 +1,109 @@
+package agent
+
+import (
+	"context"
+	"os"
+	"strings"
+	"testing"
+)
+
+// Built at run time so no literal in the source matches the secret signatures
+// that px1's own privacy check blocks reports for.
+var guardSecret = "sk-live-" + strings.Repeat("a", 26)
+
+func guardedFixture(t *testing.T) (Guarded, fixture) {
+	t.Helper()
+	f := newFixture(t)
+	write(t, f.repo.Root, ".env", "OPENAI_API_KEY="+guardSecret+"\n")
+	write(t, f.repo.Root, "pkg/config.go", "package pkg\n\nconst key = \""+guardSecret+"\"\nconst needle = \"needle\"\n")
+	runGit(t, f.repo.Root, "add", "-A")
+	runGit(t, f.repo.Root, "commit", "-qm", "add secrets")
+	f.scope.HeadSHA = runGit(t, f.repo.Root, "rev-parse", "HEAD")
+	// The fixture's hostile config also fires on the setup commits above, so
+	// clear the marker: only what the tools do from here on should count.
+	_ = os.Remove(f.marker)
+	guard := Guarded{
+		Repo: f.repo,
+		Allow: func(p string) (bool, string) {
+			if p == ".env" || strings.HasPrefix(p, "d:ir/") {
+				return false, "excluded"
+			}
+			return true, ""
+		},
+		Redact: func(text string) string {
+			return strings.ReplaceAll(text, guardSecret, "[redacted secret]")
+		},
+	}
+	return guard, f
+}
+
+func TestGuardedToolsHonourThePrivacyPolicyEverywhere(t *testing.T) {
+	g, f := guardedFixture(t)
+	ctx := context.Background()
+	if _, err := g.ReadLines(ctx, f.scope, ".env", 1, 5); err == nil || !strings.Contains(err.Error(), "excluded") {
+		t.Fatalf("excluded file read: %v", err)
+	}
+	if _, err := g.Blame(ctx, f.scope, ".env", 1, 1); err == nil {
+		t.Fatal("excluded file blamed")
+	}
+	if _, err := g.Log(ctx, f.scope, ".env", 3); err == nil {
+		t.Fatal("excluded file history read")
+	}
+	if _, err := g.ReadLines(ctx, f.scope, "../escape", 1, 1); err == nil {
+		t.Fatal("path escape accepted")
+	}
+	hits, err := g.Search(ctx, f.scope, "needle", 10)
+	if err != nil {
+		t.Fatal(err)
+	}
+	for _, hit := range hits {
+		if strings.HasPrefix(hit.Path, "d:ir/") {
+			t.Fatalf("search leaked an excluded path: %#v", hit)
+		}
+	}
+	if len(hits) == 0 {
+		t.Fatal("search lost the allowed hits")
+	}
+	if secrets, _ := g.Search(ctx, f.scope, "OPENAI_API_KEY", 10); len(secrets) != 0 {
+		t.Fatalf("search found text in an excluded file: %#v", secrets)
+	}
+	listing, err := g.ListFiles(ctx, f.scope, "")
+	if err != nil {
+		t.Fatal(err)
+	}
+	for _, entry := range listing {
+		if entry == ".env" {
+			t.Fatalf("an excluded file is visible in the listing: %v", listing)
+		}
+	}
+	if !strings.Contains(strings.Join(listing, ","), "pkg/") {
+		t.Fatalf("listing lost allowed entries: %v", listing)
+	}
+}
+
+func TestGuardedToolsRedactSecretsInAllowedFiles(t *testing.T) {
+	g, f := guardedFixture(t)
+	read, err := g.ReadLines(context.Background(), f.scope, "pkg/config.go", 1, 10)
+	if err != nil || strings.Contains(read, guardSecret) || !strings.Contains(read, "[redacted secret]") {
+		t.Fatalf("read = %q %v", read, err)
+	}
+	hits, err := g.Search(context.Background(), f.scope, "sk-live-", 10)
+	if err != nil || len(hits) != 1 || strings.Contains(hits[0].Snippet, guardSecret[:16]) {
+		t.Fatalf("search snippet not redacted: %#v %v", hits, err)
+	}
+}
+
+func TestGuardedPlugsIntoTheToolbox(t *testing.T) {
+	g, f := guardedFixture(t)
+	box := Toolbox{Files: g, Lister: g, Search: g, History: g}
+	if _, err := box.Dispatch(context.Background(), f.scope, Call{Name: ReadFile, Arguments: []byte(`{"path":".env","start_line":1,"end_line":2}`)}); err == nil {
+		t.Fatal("the toolbox read an excluded file")
+	}
+	result, err := box.Dispatch(context.Background(), f.scope, Call{Name: ReadFile, Arguments: []byte(`{"path":"pkg/config.go","start_line":1,"end_line":4}`)})
+	if err != nil || strings.Contains(result.Content, guardSecret) {
+		t.Fatalf("result=%q err=%v", result.Content, err)
+	}
+	if f.ran() {
+		t.Fatal("a guarded call ran repository-configured code")
+	}
+}

diff --git a/internal/hosted/agent/pipeline.go b/internal/hosted/agent/pipeline.go
new file mode 100644
index 0000000..0d9ae1b
--- /dev/null
+++ b/internal/hosted/agent/pipeline.go
@@ -0,0 +1,333 @@
+package agent
+
+import (
+	"context"
+	"errors"
+	"fmt"
+	"sort"
+	"strings"
+
+	"px1/internal/hosted/llm"
+	"px1/internal/hosted/review"
+)
+
+// ReviewFile is one changed file as the models see it. Diff is the unified
+// diff with new-file line numbers on added and context lines; Changed lists
+// the new-side line ranges that were added or modified.
+type ReviewFile struct {
+	Path    string
+	Diff    string
+	Changed []review.DiffRange
+}
+
+type PipelineInput struct {
+	Title, Body string
+	Files       []ReviewFile
+	Blocks      []review.Block
+}
+
+type StageNote struct{ Stage, Message string }
+
+type PipelineResult struct {
+	// Findings survived the verifier. Only these may be shown as verified.
+	Findings []review.Finding
+	// Unanchored are verified findings whose lines are not all inside a changed
+	// range. They are still in Findings; this says which ones.
+	Unanchored []review.SummaryFinding
+	// Unverified are candidates that could not be verified, for local
+	// inspection only; they must not be presented as verified findings.
+	Unverified []review.Finding
+	Plan       []PlanTask
+	Run        RunResult
+	Candidates int
+	Judged     int
+	Notes      []StageNote
+	Spend      Spend
+}
+
+// Pipeline runs plan → parallel sub-agents → judge → verifier for one review.
+// Every stage that depends on imperfect model output has a fallback that
+// narrows rather than widens the result.
+type Pipeline struct {
+	Model         Model
+	Box           Toolbox
+	Scope         Scope
+	Limiter       *OrgLimiter
+	MinConfidence float64
+	OnPartial     func(Partial)
+	// OnStage is called as each stage starts, for progress output.
+	OnStage func(stage string)
+}
+
+func (p Pipeline) stage(name string) {
+	if p.OnStage != nil {
+		p.OnStage(name)
+	}
+}
+
+func (p Pipeline) Run(ctx context.Context, in PipelineInput) (PipelineResult, error) {
+	var result PipelineResult
+	if p.Model.Meter == nil || p.Limiter == nil || len(in.Blocks) == 0 || len(in.Files) == 0 {
+		return result, errors.New("pipeline needs a metered model, limiter, change groups, and files")
+	}
+	budget := p.Model.Meter.budget
+	note := func(stage, format string, args ...any) {
+		message := fmt.Sprintf(format, args...)
+		result.Notes = append(result.Notes, StageNote{Stage: stage, Message: message})
+		if p.Model.Trace != nil {
+			p.Model.Trace.Note(stage, "stage_note", message)
+		}
+	}
+	finish := func(err error) (PipelineResult, error) {
+		result.Spend = p.Model.Meter.Spend()
+		return result, err
+	}
+	files := map[string]ReviewFile{}
+	var changedPaths []string
+	var changed []review.DiffRange
+	for _, file := range in.Files {
+		files[file.Path] = file
+		changedPaths = append(changedPaths, file.Path)
+		changed = append(changed, file.Changed...)
+	}
+	sort.Strings(changedPaths)
+
+	// 1. Plan.
+	p.stage("planning")
+	plan, err := p.plan(ctx, in, budget, changedPaths, files, note)
+	if err != nil {
+		return finish(err)
+	}
+	result.Plan = plan
+
+	// 2. Sub-agents.
+	p.stage("investigating")
+	inputs := map[string]SubAgentInput{}
+	blocks := map[string]review.Block{}
+	for _, block := range in.Blocks {
+		blocks[block.ID] = block
+	}
+	for _, task := range plan {
+		diff := blockDiff(blocks[task.BlockID], files, note)
+		inputs[task.BlockID] = SubAgentInput{Task: task, Block: blocks[task.BlockID], Diff: diff, ToolCalls: budget.MaxToolCallsPerAgent}
+	}
+	runner := Runner{Limiter: p.Limiter, Trace: p.Model.Trace, OnPartial: p.OnPartial, SubAgent: func(ctx context.Context, task PlanTask, _ *Meter) ([]review.Finding, error) {
+		return Loop{Model: p.Model, Box: p.Box, Scope: p.Scope}.Run(ctx, inputs[task.BlockID])
+	}}
+	run, err := runner.Run(ctx, p.Scope.InstallationID, plan, p.Model.Meter)
+	if err != nil {
+		return finish(err)
+	}
+	result.Run = run
+	for _, task := range plan {
+		if outcome := run.Outcomes[task.BlockID]; outcome.Outcome != TaskCompleted {
+			note("investigating", "change group %s did not finish: %s", task.BlockID, outcome.Reason)
+		}
+	}
+
+	// 3. Keep only candidates about changed files, then collapse duplicates.
+	var candidates []review.Finding
+	for _, finding := range run.Candidates {
+		if _, ok := files[finding.Path]; !ok {
+			note("investigating", "dropped a finding about %s, which this change did not touch", finding.Path)
+			continue
+		}
+		candidates = append(candidates, finding)
+	}
+	candidates = review.RankAndCapFindings(candidates, MaxCandidates)
+	result.Candidates = len(candidates)
+	if len(candidates) == 0 {
+		note("investigating", "no candidate findings; this is not a statement that the change is correct")
+		return finish(nil)
+	}
+
+	// 4. Judge: merge and narrow. Never widen.
+	p.stage("judging")
+	judged := p.judge(ctx, candidates, note)
+	result.Judged = len(judged)
+
+	// 5. Verify. Only verified findings are reported as findings.
+	p.stage("verifying")
+	verified, err := p.verify(ctx, judged, files, note)
+	if err != nil {
+		result.Unverified = judged
+		note("verifying", "verification did not complete (%v); %d candidates are not reported as verified", err, len(judged))
+		return finish(nil)
+	}
+	result.Findings = review.RankAndCapFindings(verified, MaxJudgedFindings)
+	if len(changed) > 0 && len(result.Findings) > 0 {
+		_, unanchored, err := review.MapFindingsToDiff(result.Findings, changed)
+		if err == nil {
+			result.Unanchored = unanchored
+		}
+	}
+	return finish(nil)
+}
+
+func (p Pipeline) plan(ctx context.Context, in PipelineInput, budget Budget, changedPaths []string, files map[string]ReviewFile, note func(string, string, ...any)) ([]PlanTask, error) {
+	fallback := func(why string) []PlanTask {
+		note("planning", "%s; reviewing the largest change groups with a generic focus", why)
+		return FallbackPlan(in.Blocks, func(b review.Block) int {
+			total := 0
+			for _, path := range b.Paths {
+				total += len(files[path].Diff)
+			}
+			return total
+		}, budget)
+	}
+	prompt, err := PlannerPrompt(PlanInput{Title: in.Title, Body: in.Body, Blocks: in.Blocks, Tools: p.Box.Specs(), Budget: budget, ChangedPaths: changedPaths})
+	if err != nil {
+		return nil, err
+	}
+	planner := p.Model
+	planner.MaxOutputTokens = min(p.Model.MaxOutputTokens, 2_000)
+	reply, err := planner.Call(ctx, "planner", "planner", prompt)
+	if errors.Is(err, ErrBudgetExhausted) || ctx.Err() != nil {
+		return nil, err
+	}
+	if err != nil {
+		return fallback("the planner call failed"), nil
+	}
+	tasks, problems := DecodePlanLenient(reply, in.Blocks, budget)
+	for _, problem := range problems {
+		note("planning", "%s", problem)
+	}
+	if len(tasks) == 0 {
+		return fallback("the planner returned no usable tasks"), nil
+	}
+	return tasks, nil
+}
+
+func (p Pipeline) judge(ctx context.Context, candidates []review.Finding, note func(string, string, ...any)) []review.Finding {
+	prompt, err := JudgePrompt(candidates)
+	if err != nil {
+		note("judging", "judge skipped: %v", err)
+		return candidates
+	}
+	judge := p.Model
+	judge.MaxOutputTokens = max(p.Model.MaxOutputTokens, min(len(candidates)*400, 12_000))
+	reply, err := judge.Call(ctx, "judge", "judge", prompt)
+	if err != nil {
+		note("judging", "the judge call failed; keeping all %d candidates", len(candidates))
+		return candidates
+	}
+	kept, dropped, err := DecodeJudgmentLenient(reply, candidates)
+	if err != nil {
+		note("judging", "the judge reply was unusable (%v); keeping all %d candidates", err, len(candidates))
+		return candidates
+	}
+	for _, drop := range dropped {
+		note("judging", "dropped judged finding %q: %s", drop.Title, drop.Reason)
+	}
+	// An explicit empty list is the judge discarding every candidate, which is
+	// its job. A reply whose every entry was invalid is a broken judge, and
+	// must not erase real candidates.
+	if len(kept) == 0 && len(dropped) > 0 {
+		note("judging", "every judged entry was invalid; keeping all %d candidates", len(candidates))
+		return candidates
+	}
+	note("judging", "%d candidates merged into %d findings", len(candidates), len(kept))
+	return kept
+}
+
+func (p Pipeline) verify(ctx context.Context, findings []review.Finding, files map[string]ReviewFile, note func(string, string, ...any)) ([]review.Finding, error) {
+	if len(findings) == 0 {
+		return nil, nil
+	}
+	candidates := make([]review.VerificationCandidate, len(findings))
+	byID := map[string]review.Finding{}
+	for i, finding := range findings {
+		id := fmt.Sprintf("f%d", i+1)
+		candidates[i] = review.VerificationCandidate{ID: id, Path: finding.Path, StartLine: finding.StartLine, EndLine: finding.EndLine, Title: finding.Title, Evidence: finding.Evidence, Context: diffContext(files[finding.Path].Diff, finding.StartLine, finding.EndLine)}
+		byID[id] = finding
+	}
+	model := p.Model
+	model.MaxOutputTokens = max(p.Model.MaxOutputTokens, min(len(findings)*200+500, 6_000))
+	verifier := review.FindingVerifier{Client: cleaningClient{model: model}, Provider: p.Model.Provider, Model: p.Model.Name, PromptVersion: "px1-agentic-1", MinConfidence: p.MinConfidence, MaxOutputTokens: model.MaxOutputTokens}
+	var result review.VerificationResult
+	var err error
+	for attempt := 0; attempt < 2; attempt++ {
+		if result, err = verifier.Verify(ctx, candidates); err == nil || errors.Is(err, ErrBudgetExhausted) || ctx.Err() != nil {
+			break
+		}
+		note("verifying", "verification attempt %d failed: %v", attempt+1, err)
+	}
+	if err != nil {
+		return nil, err
+	}
+	kept := make([]review.Finding, 0, len(result.Kept))
+	for _, candidate := range result.Kept {
+		kept = append(kept, byID[candidate.ID])
+	}
+	ids := make([]string, 0, len(result.Dropped))
+	for id := range result.Dropped {
+		ids = append(ids, id)
+	}
+	sort.Strings(ids)
+	for _, id := range ids {
+		note("verifying", "verifier dropped %q: %s", byID[id].Title, result.Dropped[id])
+	}
+	return kept, nil
+}
+
+// cleaningClient lets the metered model act as the verifier's client. The
+// verifier insists on a bare JSON array and rejects unknown fields; models
+// often wrap the array in a code fence or a sentence. The client extracts the
+// array, and the verifier's strict rules then apply to what it contains.
+type cleaningClient struct{ model Model }
+
+func (c cleaningClient) Complete(ctx context.Context, request llm.Request) (llm.Response, error) {
+	text, err := c.model.Call(ctx, "verifier", "verifier", Prompt{System: request.System, User: request.Prompt})
+	if err != nil {
+		return llm.Response{}, err
+	}
+	if raw, jsonErr := firstJSON(text); jsonErr == nil {
+		text = string(raw)
+	}
+	return llm.Response{Text: text}, nil
+}
+
+// blockDiff joins the numbered diffs of a change group's files, cutting at the
+// prompt limit rather than failing the whole group.
+func blockDiff(block review.Block, files map[string]ReviewFile, note func(string, string, ...any)) string {
+	var out strings.Builder
+	for _, path := range block.Paths {
+		file, ok := files[path]
+		if !ok {
+			continue
+		}
+		section := "=== " + path + " ===\n" + file.Diff + "\n"
+		if out.Len()+len(section) > maxDiffBytes {
+			room := maxDiffBytes - out.Len() - 80
+			if room > 200 {
+				out.WriteString(clip(section, room))
+			}
+			out.WriteString("\n[diff truncated by px1: use read_file for the rest]\n")
+			note("investigating", "the diff for change group %s was cut at %d bytes", block.ID, maxDiffBytes)
+			break
+		}
+		out.WriteString(section)
+	}
+	return out.String()
+}
+
+// diffContext returns the numbered diff lines near a finding, bounded so a
+// verifier request stays small.
+func diffContext(diff string, start, end int) string {
+	lines := strings.Split(diff, "\n")
+	var picked []string
+	for _, line := range lines {
+		number, _, ok := strings.Cut(line, "\t")
+		if !ok {
+			continue
+		}
+		var n int
+		if _, err := fmt.Sscanf(number, "%d", &n); err != nil {
+			continue
+		}
+		if n >= start-6 && n <= end+6 {
+			picked = append(picked, line)
+		}
+	}
+	return clip(strings.Join(picked, "\n"), 2_000)
+}

diff --git a/internal/hosted/agent/pipeline_test.go b/internal/hosted/agent/pipeline_test.go
new file mode 100644
index 0000000..5154493
--- /dev/null
+++ b/internal/hosted/agent/pipeline_test.go
@@ -0,0 +1,331 @@
+package agent
+
+import (
+	"context"
+	"errors"
+	"fmt"
+	"strings"
+	"sync"
+	"testing"
+	"time"
+
+	"px1/internal/hosted/llm"
+	"px1/internal/hosted/review"
+)
+
+// roleModel answers each pipeline role with its own handler. Roles are
+// recognized by their system prompts, so the fake is safe under the parallel
+// runner.
+type roleModel struct {
+	mu       sync.Mutex
+	handlers map[string]func(call int, request llm.Request) (string, error)
+	calls    map[string]int
+}
+
+func roleOf(system string) string {
+	switch {
+	case strings.Contains(system, "You are the planner"):
+		return "planner"
+	case strings.Contains(system, "review sub-agent"):
+		return "sub-agent"
+	case strings.Contains(system, "You are the px1 judge"):
+		return "judge"
+	case strings.Contains(system, "Verify each proposed"):
